import '../widgets/app_scaffold.dart';

class WorkerDetailsScreen extends StatelessWidget { const WorkerDetailsScreen({super.key}); @override Widget build(BuildContext context) { final worker = ModalRoute.of(context)?.settings.arguments as Worker?; final person = worker ?? const Worker(name: 'Md. Maruf Siddiki', email: 'maruf@company.com', country: 'Bangladesh', role: 'Senior Developer', engagementType: 'Employee', complianceStatus: 'Compliant', salary: 8200, documents: ['Passport.pdf', 'Tax_SG.pdf']); return AppScaffold(title: 'Employee Details', child: ListView(padding: const EdgeInsets.fromLTRB(24, 16, 24, 24), children: [SurfaceCard(child: Column(children: [const CircleAvatar(radius: 42, backgroundColor: mint, child: Icon(Icons.person, size: 50, color: green)), const SizedBox(height: 12), Text(person.name, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w800)), Text(person.role, style: const TextStyle(color: muted)), const SizedBox(height: 14), Row(mainAxisAlignment: MainAxisAlignment.center, children: [StatusBadge(text: '🇧🇩${person.country}'), const SizedBox(width: 8), StatusBadge(text: person.engagementType)]), const Divider(height: 28), StatusBadge(text: '✓ Fully Compliant')])), const SizedBox(height: 20), const Text('Workspace Details', style: TextStyle(fontWeight: FontWeight.w700)), const SizedBox(height: 10), SurfaceCard(child: Column(children: [detail('Tax Identification', 'ID: 987654-A'), detail('Monthly Salary', '\$${person.salary.toStringAsFixed(2)} / mo'), detail('Payment Schedule', 'Monthly')])), const SizedBox(height: 20), const Text('Key Documents', style: TextStyle(fontWeight: FontWeight.w700)), const SizedBox(height: 10), Row(children: person.documents.take(2).map((doc) => Expanded(child: Padding(padding: const EdgeInsets.only(right: 8), child: SurfaceCard(child: Text('▧  $doc', style: const TextStyle(fontWeight: FontWeight.w700)))))).toList())])); }
 Widget detail(String label, String value) => Padding(padding: const EdgeInsets.symmetric(vertical: 9), child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(label, style: const TextStyle(color: muted)), Text(value, style: const TextStyle(fontWeight: FontWeight.w700))])); }
